import React, { useEffect, useState, useCallback } from 'react';
import { Dropdown } from 'react-bootstrap';

interface ActiveUser {
  userId: string;
  problemId: string;
}

interface Props {
  token: string;
}

const ActiveUsersDropdown: React.FC<Props> = ({ token }) => {
  const [activeUserCount, setActiveUserCount] = useState<number | null>(null);
  const [activeUsersProblems, setActiveUsersProblems] = useState<Record<number, string[]>>({});
  const [problemTitles, setProblemTitles] = useState<Record<number, string>>({});

  const fetchProblemTitles = async (problemIds: number[]): Promise<Record<number, string>> => {
    const titles: Record<number, string> = {};
    try {
      const membershipId = localStorage.getItem('membershipId');
      if (!membershipId) throw new Error('Membership ID not found');

      const response = await fetch(
        `https://ec2-3-34-134-27.ap-northeast-2.compute.amazonaws.com/api/problems/completed?userId=${membershipId}&type=WARGAME&kind=&sortKind=&desc=true&page=0&size=25`,
        {
          method: 'GET',
          headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
        }
      );

      if (response.ok) {
        const data = await response.json();
        data.content.forEach((item: { id: number; title: string }) => {
          if (problemIds.includes(item.id)) titles[item.id] = item.title;
        });
      } else {
        console.error('Failed to fetch problem titles:', response.status);
      }
    } catch (error) {
      console.error('Error fetching problem titles:', error);
    }
    return titles;
  };

  const fetchUserProblemsTitles = useCallback(
    async (activeUsersData: ActiveUser[]) => {
      try {
        const activeUsersProblems: Record<number, string[]> = {};
        const problemIds: number[] = [];

        activeUsersData.forEach(({ userId, problemId }) => {
          const problemIdNum = parseInt(problemId, 10);
          if (!activeUsersProblems[problemIdNum]) activeUsersProblems[problemIdNum] = [];
          activeUsersProblems[problemIdNum].push(userId);

          if (!problemIds.includes(problemIdNum)) problemIds.push(problemIdNum);
        });

        const titles = await fetchProblemTitles(problemIds);
        setProblemTitles(titles);
        setActiveUsersProblems(activeUsersProblems);
      } catch (error) {
        console.error('Error fetching user problems titles:', error);
      }
    },
    [token]
  );

  const fetchActiveUsers = useCallback(async () => {
    try {
      const response = await fetch(
        'https://ec2-3-34-134-27.ap-northeast-2.compute.amazonaws.com/api/pods/active?namespace=wargame',
        {
          method: 'GET',
          headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
        }
      );

      if (response.ok) {
        const data = await response.json();
        setActiveUserCount(data.length);
        fetchUserProblemsTitles(data);
      } else {
        console.error('Failed to fetch active users:', response.status);
        setActiveUserCount(null);
      }
    } catch (error) {
      console.error('Error fetching active users:', error);
      setActiveUserCount(null);
    }
  }, [token, fetchUserProblemsTitles]);

  useEffect(() => {
    if (token) {
      fetchActiveUsers();
    }
  }, [token, fetchActiveUsers]);

  return (
    <Dropdown className="mr-3">
      <Dropdown.Toggle
        id="dropdown-active-users"
        style={{ backgroundColor: 'transparent', border: 'none', color: '#000', fontSize: '16px', padding: '0 10px' }}
      >
        {activeUserCount !== null ? `현재 접속인원: ${activeUserCount}명` : '접속 중 사용자 수'}
      </Dropdown.Toggle>

      <Dropdown.Menu style={{ background: 'transparent' }}>
        {Object.keys(activeUsersProblems).map((problemId) => {
          const problemIdNumber = Number(problemId);
          const problemTitle = problemTitles?.[problemIdNumber];

          if (activeUsersProblems?.[problemId]?.length > 0) {
            return (
              <Dropdown.Item
                key={problemId}
                style={{ width: '100%', padding: '10px', boxSizing: 'border-box', transition: 'background-color 0.3s ease, color 0.3s ease' }}
                onMouseOver={(e) => {
                  const target = e.target as HTMLElement;
                  target.style.backgroundColor = '#c0c0cb';
                  target.style.color = '#fff';
                }}
                onMouseOut={(e) => {
                  const target = e.target as HTMLElement;
                  target.style.backgroundColor = '';
                  target.style.color = '';
                }}
              >
                {problemTitle || `문제 ID ${problemId}`} : {activeUsersProblems[problemId].length}명
              </Dropdown.Item>
            );
          }
          return null;
        })}
      </Dropdown.Menu>
    </Dropdown>
  );
};

export default ActiveUsersDropdown;
